import type { Benchmark, Category } from "../types/benchmark";
import catalog from "../../.generated/catalog.json";
import categoryData from "../../.generated/categories.json";

// Generated by the validated content pipeline; source drafts never reach this module.
export const allBenchmarks = catalog as Benchmark[];
export const benchmarks = allBenchmarks.filter(
  (item) => item.status === "published",
);
export const categories = categoryData as Category[];
export const byId = new Map(allBenchmarks.map((item) => [item.id, item]));
export const categoryById = new Map(categories.map((item) => [item.id, item]));
export const kindLabels = {
  original: "独立评测",
  subset: "评测子集",
  derivative: "衍生评测",
  suite: "评测体系",
  internal: "内部评测",
} as const;
